INSERT INTO `v1_5d09d40183ffb87e06f6ca96cab343a27930576a2d676e5a3975ae39e2380f85` VALUES ("もうすぐ、みなさまに\nお会いできるのですね。\n胸が高鳴ってしまいます……\n", 125801, 2, 1, 40011, 0, 24001, 1, 1, 321, "リリ");
INSERT INTO `v1_5d09d40183ffb87e06f6ca96cab343a27930576a2d676e5a3975ae39e2380f85` VALUES ("初めまして、クリアです♪\nみなさんと一緒に冒険するの\nとっても楽しみにしてます", 126001, 2, 2, 40011, 0, 24001, 1, 1, 322, "クリア");
INSERT INTO `v1_5d09d40183ffb87e06f6ca96cab343a27930576a2d676e5a3975ae39e2380f85` VALUES ("んーと。\nこれ、あげる。\nはい", 126101, 2, 3, 40011, 0, 24001, 1, 1, 323, "プレシア");
INSERT INTO `v1_5d09d40183ffb87e06f6ca96cab343a27930576a2d676e5a3975ae39e2380f85` VALUES ("あらためまして……\n【アルターメイデン】の\nギルドマスター、リリと申します", 125801, 2, 4, 40011, 0, 24001, 2, 1, 324, "リリ");
INSERT INTO `v1_5d09d40183ffb87e06f6ca96cab343a27930576a2d676e5a3975ae39e2380f85` VALUES ("こんにちは、お兄さん♪\n【アルターメイデン】の\nクリアです", 126001, 2, 5, 40011, 0, 24001, 2, 1, 325, "クリア");
INSERT INTO `v1_5d09d40183ffb87e06f6ca96cab343a27930576a2d676e5a3975ae39e2380f85` VALUES ("お兄。\nきてくれて、うれしい", 126101, 2, 6, 40011, 0, 24001, 2, 1, 326, "プレシア");
